package com.acme.bank.accounts;

import java.math.BigDecimal;

/**
 * Guards a debit against insufficient available funds, taking holds into account.
 */
public class FundsSufficiencyGuard {

    private final AccountRepository accounts;

    public FundsSufficiencyGuard(AccountRepository accounts) {
        this.accounts = accounts;
    }

    public void assertSufficient(String accountNumber, BigDecimal amount) {
        Account a = accounts.require(accountNumber);
        BigDecimal available = a.getBalance().subtract(a.getHeldAmount());
        if (amount.signum() <= 0) {
            throw new IllegalArgumentException("Debit amount must be positive");
        }
        if (amount.compareTo(available) > 0) {
            throw new InsufficientFundsException(accountNumber, available, amount);
        }
    }
}

class InsufficientFundsException extends RuntimeException {
    public InsufficientFundsException(String acc, BigDecimal avail, BigDecimal req) {
        super("Account " + acc + " available " + avail + " but requested " + req);
    }
}

