package com.acme.bank.transfers;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * Executes an internal transfer atomically within a single database transaction.
 */
public class InternalTransferService {

    private final AccountRepository accounts;
    private final LedgerRepository ledger;
    private final TransactionTemplate tx;

    public InternalTransferService(AccountRepository accounts,
                                   LedgerRepository ledger,
                                   TransactionTemplate tx) {
        this.accounts = accounts;
        this.ledger = ledger;
        this.tx = tx;
    }

    public TransferReceipt transfer(String from, String to, BigDecimal amount) {
        return tx.execute(status -> {
            Account source = accounts.requireForUpdate(from);
            Account target = accounts.requireForUpdate(to);
            if (source.getAvailable().compareTo(amount) < 0) {
                throw new InsufficientFundsException(from, source.getAvailable(), amount);
            }
            source.debit(amount);
            target.credit(amount);
            accounts.save(source);
            accounts.save(target);
            Transfer t = ledger.record(from, to, amount, Instant.now());
            return new TransferReceipt(t.getId(), t.getOccurredAt());
        });
    }
}

