/**
 * Payment submission endpoint: validate target, check funds, hand off to processor.
 */
@RestController
public class PaymentSubmissionController {

    private final AccountDirectory directory;
    private final FundsSufficiencyGuard funds;
    private final PaymentProcessor processor;

    public PaymentSubmissionController(AccountDirectory directory,
                                       FundsSufficiencyGuard funds,
                                       PaymentProcessor processor) {
        this.directory = directory;
        this.funds = funds;
        this.processor = processor;
    }

    @PostMapping("/payments")
    public PaymentReceipt submit(@RequestParam String fromAccount,
                                 @RequestParam String payeeAccount,
                                 @RequestParam BigDecimal amount) {
        if (!directory.exists(payeeAccount)) {
            throw new UnknownPayeeException(payeeAccount);
        }
        funds.assertSufficient(fromAccount, amount);
        return processor.submit(fromAccount, payeeAccount, amount);
    }
}

