package com.acme.bank.ledger;

import java.math.BigDecimal;
import java.time.Instant;
import javax.persistence.EntityManager;
import javax.persistence.EntityTransaction;

/**
 * Appends an immutable entry to the account ledger for every movement.
 */
public class LedgerEntryWriter {

    private final EntityManager em;

    public LedgerEntryWriter(EntityManager em) {
        this.em = em;
    }

    public void append(String accountNumber, BigDecimal signedAmount, BigDecimal resultingBalance, String reference) {
        EntityTransaction tx = em.getTransaction();
        tx.begin();
        try {
            LedgerEntry e = new LedgerEntry();
            e.setAccountNumber(accountNumber);
            e.setSignedAmount(signedAmount);
            e.setResultingBalance(resultingBalance);
            e.setReference(reference);
            e.setRecordedAt(Instant.now());
            em.persist(e);
            tx.commit();
        } catch (RuntimeException ex) {
            tx.rollback();
            throw ex;
        }
    }
}

