CREATE TABLE ledger_entry (
    entry_id            BIGSERIAL PRIMARY KEY,
    account_number      VARCHAR(34)   NOT NULL,
    signed_amount       NUMERIC(18,2) NOT NULL,
    resulting_balance   NUMERIC(18,2) NOT NULL,
    reference           VARCHAR(80),
    recorded_at         TIMESTAMP     NOT NULL,
    CONSTRAINT ledger_account_fk FOREIGN KEY (account_number) REFERENCES account(account_number),
    CONSTRAINT ledger_amount_nonzero CHECK (signed_amount <> 0),
    CONSTRAINT ledger_balance_not_null CHECK (resulting_balance IS NOT NULL)
);

CREATE OR REPLACE FUNCTION block_closed_account_writes() RETURNS trigger AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM account WHERE account_number = NEW.account_number AND status = 'CLOSED') THEN
        RAISE EXCEPTION 'Cannot write ledger entry for closed account %', NEW.account_number;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER ledger_closed_guard BEFORE INSERT ON ledger_entry
FOR EACH ROW EXECUTE FUNCTION block_closed_account_writes();

