#include <stdio.h>
#include "bank_db.h"

int charge_monthly_fees(const char *period) {
    db_cursor_t *cur = NULL;
    if (db_open_current_account_cursor(&cur) != DB_OK) return -1;

    int charged = 0;
    account_row_t a;
    while (db_account_cursor_next(cur, &a) == DB_OK) {
        if (a.status != ACCOUNT_OPEN) continue;
        if (a.balance <= 0) continue;
        if (db_fee_already_charged(a.account_number, period)) continue;

        if (db_insert_ledger_entry(a.account_number, -a.monthly_fee,
                                   a.balance - a.monthly_fee, period) != DB_OK) {
            db_close_cursor(cur);
            return -2;
        }
        db_mark_fee_charged(a.account_number, period);
        charged++;
    }
    db_close_cursor(cur);
    return charged;
}

